37|const toActionResult = (
38|  result: { ok: true; data: unknown } | { ok: false; summary: string; error: string },
39|): ActionExecutionResult => {
40|  if (result.ok) {
41|    return { status: 'SUCCEEDED', output: result.data as JsonValue };
42|  }
43|  const errorClass = VALIDATION_ERRORS.has(result.error)
44|    ? 'VALIDATION'
45|    : result.error === 'url_blocked'
46|      ? 'SSRF_BLOCKED'
47|      : 'EXTERNAL_ERROR';
48|  return {
49|    status: 'FAILED',
50|    errorCode: result.error.replace(/-/g, '_').toUpperCase(),
51|    errorClass,
52|    safeMessage: result.summary,
53|  };
54|};
